// PRIMARY: beacon_chain/spec/state_transition_block.nim:process_deposit_request (lines 371-392)
// nimbus-eth2 processes DepositRequest objects received from the Engine API. The raw 576-byte
// validation is an EL concern, but nimbus-eth2 validates DepositRequest SSZ fields here.
func process_deposit_request*(
    cfg: RuntimeConfig,
    state: var (electra.BeaconState | fulu.BeaconState | gloas.BeaconState),
    deposit_request: DepositRequest,
    flags: UpdateFlags): Result[void, cstring] =
  # Set deposit request start index
  if state.deposit_requests_start_index == UNSET_DEPOSIT_REQUESTS_START_INDEX:
    state.deposit_requests_start_index = deposit_request.index
  # Create pending deposit
  if state.pending_deposits.add(PendingDeposit(
      pubkey: deposit_request.pubkey,
      withdrawal_credentials: deposit_request.withdrawal_credentials,
      amount: deposit_request.amount,
      signature: deposit_request.signature,
      slot: state.slot)):
    ok()
  else:
    err("process_deposit_request: couldn't add deposit to pending_deposits")

// PRIMARY: beacon_chain/spec/peerdas_helpers.nim:compute_matrix (lines 90-108)
// polynomial_eval_to_coeff (bit_reversal + inverse FFT) is implemented in the kzg4844 C library
// called via computeCellsAndKzgProofs. nimbus-eth2 delegates all KZG polynomial operations
// to the kzg4844 library. The compute_matrix function calls computeCellsAndKzgProofs(blob)
// which internally uses polynomial_eval_to_coeff.
proc compute_matrix*(blobs: seq[KzgBlob]): Result[seq[MatrixEntry], cstring] =
  for blbIdx, blob in blobs.pairs:
    let cellsAndProofs = computeCellsAndKzgProofs(blob)
    if cellsAndProofs.isErr:
      return err("Computing Extended Matrix: Issue computing cells and proofs")

