// PRIMARY: beacon_chain/spec/peerdas_helpers.nim:compute_matrix (lines 90-108)
// Cell-proof alignment: computeCellsAndKzgProofs returns aligned cells[i] and proofs[i] pairs.
// compute_matrix verifies alignment by storing (cell, kzg_proof) at the same row_index/column_index.
proc compute_matrix*(blobs: seq[KzgBlob]): Result[seq[MatrixEntry], cstring] =
  for blbIdx, blob in blobs.pairs:
    let cellsAndProofs = computeCellsAndKzgProofs(blob)
    for i in 0..<fulu.CELLS_PER_EXT_BLOB:
      extended_matrix.add(MatrixEntry(
        cell: cellsAndProofs.get.cells[i],
        kzg_proof: cellsAndProofs.get.proofs[i],  // aligned by index
        row_index: blbIdx.uint64,
        column_index: i.uint64))

