// 50% threshold and cell index uniqueness/bounds are validated by kzg4844 C library internals.
// nimbus-eth2 checks non-empty data_columns but does NOT explicitly check the 50% threshold;
// this is delegated to recoverCellsAndKzgProofs in kzg4844.
proc recover_cells_and_proofs*(data_columns: seq[ref fulu.DataColumnSidecar]):
    Result[seq[CellsAndProofs], cstring] =
  if data_columns.len == 0:
    return err("DataColumnSidecar: Length should not be 0")
  for data_column in data_columns:
    if not (blobCount == data_column.column.len):
      return err("DataColumns do not have the same length")

